module ComfyUI.Assets.CreditsPanelBlm1wFo9JsMap

let file = """{"version":3,"file":"CreditsPanel-Blm1wFo9.js","names":["$t","$t","$t"],"sources":["../../src/services/customerEventsService.ts","../../src/components/dialog/content/setting/UsageLogsTable.vue","../../src/components/dialog/content/setting/UsageLogsTable.vue","../../src/platform/cloud/subscription/composables/useSubscriptionCredits.ts","../../src/platform/cloud/subscription/utils/creditsProgress.ts","../../src/platform/cloud/subscription/components/CreditsTile.vue","../../src/platform/cloud/subscription/components/CreditsTile.vue","../../src/components/dialog/content/setting/CreditsPanel.vue","../../src/components/dialog/content/setting/CreditsPanel.vue"],"sourcesContent":["import type { AxiosError, AxiosResponse } from 'axios'\nimport axios from 'axios'\nimport { ref, watch } from 'vue'\n\nimport { webSessionResourceHeader } from '@/platform/auth/session/webSessionFetch'\nimport { attachUnifiedRemintInterceptor } from '@/platform/auth/unified/remintRetry'\nimport { getComfyApiBaseUrl } from '@/config/comfyApi'\nimport { d, t } from '@/i18n'\nimport { useAuthStore } from '@/stores/authStore'\nimport type { components, operations } from '@/types/comfyRegistryTypes'\nimport { isAbortError } from '@/utils/typeGuardUtil'\n\nexport enum EventType {\n  CREDIT_ADDED = 'credit_added',\n  ACCOUNT_CREATED = 'account_created',\n  API_USAGE_STARTED = 'api_usage_started',\n  API_USAGE_COMPLETED = 'api_usage_completed'\n}\n\ntype CustomerEventsResponse =\n  operations['GetCustomerEvents']['responses']['200']['content']['application/json']\n\ntype CustomerEventsResponseQuery =\n  operations['GetCustomerEvents']['parameters']['query']\n\nexport type AuditLog = components['schemas']['AuditLog']\n\nconst customerApiClient = axios.create({\n  baseURL: getComfyApiBaseUrl(),\n  headers: {\n    'Content-Type': 'application/json'\n  }\n})\n\nattachUnifiedRemintInterceptor(customerApiClient)\n\nexport const useCustomerEventsService = () => {\n  const isLoading = ref(false)\n  const error = ref<string | null>(null)\n  let latestRequestId = 0\n\n  watch(\n    () => getComfyApiBaseUrl(),\n    (url) => {\n      customerApiClient.defaults.baseURL = url\n    }\n  )\n\n  const describeRequestError = (\n    err: unknown,\n    context: string,\n    routeSpecificErrors?: Record<number, string>\n  ): string | null => {\n    // Don't treat cancellation as an error\n    if (isAbortError(err)) return null\n\n    if (!axios.isAxiosError(err)) {\n      return `${context} failed: ${err instanceof Error ? err.message : String(err)}`\n    }\n    const axiosError = err as AxiosError<{ message: string }>\n    const status = axiosError.response?.status\n    if (status && routeSpecificErrors?.[status]) {\n      return routeSpecificErrors[status]\n    }\n    return (\n      axiosError.response?.data.message ??\n      `${context} failed with status ${status}`\n    )\n  }\n\n  const executeRequest = async <T>(\n    requestCall: () => Promise<AxiosResponse<T>>,\n    options: {\n      errorContext: string\n      routeSpecificErrors?: Record<number, string>\n    }\n  ): Promise<{ data: T | null; errorMessage: string | null }> => {\n    const { errorContext, routeSpecificErrors } = options\n\n    try {\n      const response = await requestCall()\n      return { data: response.data, errorMessage: null }\n    } catch (err) {\n      return {\n        data: null,\n        errorMessage: describeRequestError(\n          err,\n          errorContext,\n          routeSpecificErrors\n        )\n      }\n    }\n  }\n\n  function formatEventType(eventType: string) {\n    switch (eventType) {\n      case 'credit_added':\n      case 'topup_completed':\n        return t('credits.eventTypes.creditAdded')\n      case 'account_created':\n        return t('credits.eventTypes.accountCreated')\n      case 'api_usage_completed':\n        return t('credits.eventTypes.apiUsage')\n      case 'gpu_usage':\n        return t('credits.eventTypes.gpuUsage')\n      case 'api_node_usage':\n        return t('credits.eventTypes.apiNodeUsage')\n      default:\n        return eventType\n    }\n  }\n\n  function formatDate(dateString: string): string {\n    const date = new Date(dateString)\n\n    return d(date, {\n      month: 'short',\n      day: 'numeric',\n      hour: '2-digit',\n      minute: '2-digit'\n    })\n  }\n\n  function formatJsonKey(key: string) {\n    return key\n      .split('_')\n      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))\n      .join(' ')\n  }\n\n  function formatJsonValue(value: unknown) {\n    if (typeof value === 'number') {\n      return value.toLocaleString()\n    }\n    if (typeof value === 'string') {\n      const date = new Date(value)\n      if (!Number.isNaN(date.getTime()) && /^\\d{4}-\\d{2}-\\d{2}T/.test(value)) {\n        return d(date, { dateStyle: 'medium', timeStyle: 'short' })\n      }\n    }\n    return value\n  }\n\n  function getEventSeverity(eventType: string) {\n    switch (eventType) {\n      case 'credit_added':\n      case 'topup_completed':\n        return 'success'\n      case 'account_created':\n        return 'info'\n      case 'api_usage_completed':\n      case 'gpu_usage':\n      case 'api_node_usage':\n        return 'warning'\n      default:\n        return 'info'\n    }\n  }\n\n  function hasAdditionalInfo(event: AuditLog) {\n    const { amount, api_name, model, ...otherParams } = event.params || {}\n    return Object.keys(otherParams).length > 0\n  }\n\n  function formatAmount(amountMicros?: number) {\n    if (!amountMicros) return '0.00'\n    return (amountMicros / 100).toFixed(2)\n  }\n\n  async function getMyEvents({\n    page = 1,\n    limit = 10\n  }: CustomerEventsResponseQuery = {}): Promise<CustomerEventsResponse | null> {\n    const errorContext = 'Fetching customer events'\n    const routeSpecificErrors = {\n      400: 'Invalid input, object invalid',\n      404: 'Not found'\n    }\n\n    const authStore = useAuthStore()\n    const requestOwner = authStore.currentUserIdentity()\n    const requestId = ++latestRequestId\n    if (!authStore.hasPersonalWorkspace) {\n      isLoading.value = false\n      error.value = t('toastMessages.noPersonalWorkspace')\n      return null\n    }\n    isLoading.value = true\n    error.value = null\n\n    let authHeaders\n    try {\n      authHeaders =\n        (await webSessionResourceHeader()) ??\n        (await authStore.getUserAuthHeader())\n    } catch (err) {\n      if (requestId !== latestRequestId) return null\n      isLoading.value = false\n      error.value = describeRequestError(err, errorContext)\n      return null\n    }\n    if (requestId !== latestRequestId) {\n      return null\n    }\n    if (authStore.currentUserIdentity() !== requestOwner) {\n      isLoading.value = false\n      return null\n    }\n    if (!authHeaders) {\n      isLoading.value = false\n      error.value = 'Authentication header is missing'\n      return null\n    }\n\n    const { data, errorMessage } = await executeRequest<CustomerEventsResponse>(\n      () =>\n        customerApiClient.get('/customers/events', {\n          params: { page, limit },\n          headers: authHeaders\n        }),\n      { errorContext, routeSpecificErrors }\n    )\n\n    if (requestId !== latestRequestId) {\n      return null\n    }\n    isLoading.value = false\n    if (authStore.currentUserIdentity() !== requestOwner) {\n      return null\n    }\n    error.value = errorMessage\n    return data\n  }\n\n  return {\n    // State\n    isLoading,\n    error,\n\n    // Methods\n    getMyEvents,\n    formatEventType,\n    getEventSeverity,\n    formatAmount,\n    hasAdditionalInfo,\n    formatDate,\n    formatJsonKey,\n    formatJsonValue\n  }\n}\n","<template>\n  <div>\n    <div v-if=\"loading\" class=\"flex items-center justify-center p-8\">\n      <Spinner />\n    </div>\n    <div v-else-if=\"error\" class=\"p-4\">\n      <Message severity=\"error\">{{ error }}</Message>\n    </div>\n    <template v-else>\n      <Table>\n        <TableHeader>\n          <TableRow>\n            <TableHead>{{ $t('credits.eventType') }}</TableHead>\n            <TableHead>{{ $t('credits.details') }}</TableHead>\n            <TableHead>{{ $t('credits.time') }}</TableHead>\n            <TableHead>{{ $t('credits.additionalInfo') }}</TableHead>\n          </TableRow>\n        </TableHeader>\n        <TableBody>\n          <TableRow\n            v-for=\"(event, index) in events\"\n            :key=\"event.event_id ?? index\"\n          >\n            <TableCell>\n              <Badge\n                variant=\"badge\"\n                :severity=\"\n                  customerEventService.getEventSeverity(event.event_type ?? '')\n                \"\n              >\n                {{\n                  customerEventService.formatEventType(event.event_type ?? '')\n                }}\n              </Badge>\n            </TableCell>\n            <TableCell>\n              <div\n                v-if=\"event.event_type === EventType.CREDIT_ADDED\"\n                class=\"font-semibold text-success-background\"\n              >\n                {{ $t('credits.added') }} ${{\n                  customerEventService.formatAmount(eventAmount(event))\n                }}\n              </div>\n              <div v-else-if=\"event.event_type === EventType.ACCOUNT_CREATED\">\n                {{ $t('credits.accountInitialized') }}\n              </div>\n              <div\n                v-else-if=\"event.event_type === EventType.API_USAGE_COMPLETED\"\n                class=\"flex flex-col gap-1\"\n              >\n                <div class=\"font-semibold\">\n                  {{ event.params?.api_name || $t('credits.api') }}\n                </div>\n                <div class=\"text-sm text-muted-foreground\">\n                  {{ $t('credits.model') }}: {{ event.params?.model || '-' }}\n                </div>\n              </div>\n            </TableCell>\n            <TableCell>\n              {{ customerEventService.formatDate(event.createdAt ?? '') }}\n            </TableCell>\n            <TableCell>\n              <Button\n                v-if=\"customerEventService.hasAdditionalInfo(event)\"\n                :tooltip=\"additionalInfoTooltip(event)\"\n                variant=\"textonly\"\n                size=\"icon-sm\"\n                :aria-label=\"$t('credits.additionalInfo')\"\n              >\n                <i class=\"pi pi-info-circle\" />\n              </Button>\n            </TableCell>\n          </TableRow>\n        </TableBody>\n      </Table>\n      <Pagination\n        v-if=\"pagination.total > pagination.limit\"\n        :page=\"pagination.page\"\n        :total=\"pagination.total\"\n        :items-per-page=\"pagination.limit\"\n        class=\"mt-3\"\n        @update:page=\"onPageChange\"\n      />\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport Message from '@/components/ui/message/Message.vue'\nimport Pagination from '@/components/ui/pagination/Pagination.vue'\nimport Spinner from '@/components/ui/spinner/Spinner.vue'\nimport Table from '@/components/ui/table/Table.vue'\nimport TableBody from '@/components/ui/table/TableBody.vue'\nimport TableCell from '@/components/ui/table/TableCell.vue'\nimport TableHead from '@/components/ui/table/TableHead.vue'\nimport TableHeader from '@/components/ui/table/TableHeader.vue'\nimport TableRow from '@/components/ui/table/TableRow.vue'\nimport { formatCreditsFromUsd } from '@/base/credits/comfyCredits'\nimport { useBillingRouting } from '@/composables/billing/useBillingRouting'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { workspaceApi } from '@/platform/workspace/api/workspaceApi'\nimport { readOnRail } from '@/platform/workspace/composables/readOnRail'\nimport { useBillingReadRail } from '@/platform/workspace/composables/useBillingReadRail'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { usePendingTopup } from '@/composables/billing/usePendingTopup'\nimport type { AuditLog } from '@/services/customerEventsService'\nimport {\n  EventType,\n  useCustomerEventsService\n} from '@/services/customerEventsService'\n\nconst { t, locale } = useI18n()\n\nconst events = ref<AuditLog[]>([])\nconst loading = ref(true)\nconst error = ref<string | null>(null)\n\nconst customerEventService = useCustomerEventsService()\n\nconst { shouldUseWorkspaceBilling } = useBillingRouting()\n\nconst pagination = ref({\n  page: 1,\n  limit: 7,\n  total: 0\n})\n\nfunction toFiniteNumber(raw: unknown) {\n  const value = typeof raw === 'string' && raw.trim() ? Number(raw) : raw\n  return typeof value === 'number' && Number.isFinite(value) ? value : undefined\n}\n\nfunction eventAmount(event: AuditLog) {\n  return toFiniteNumber(event.params?.amount)\n}\n\nfunction formatChargeCredits(microUsd: number) {\n  const amount = formatCreditsFromUsd({\n    usd: microUsd / 1_000_000,\n    locale: locale.value,\n    numberOptions: { minimumFractionDigits: 0, maximumFractionDigits: 0 }\n  })\n  return `${amount} ${t('credits.credits')}`\n}\n\nfunction formatParam(key: string, value: unknown) {\n  const microUsd =\n    key === 'charge_micro_usd' ? toFiniteNumber(value) : undefined\n  if (microUsd !== undefined) {\n    return `${t('credits.charge')}: ${formatChargeCredits(microUsd)}`\n  }\n  return `${customerEventService.formatJsonKey(key)}: ${customerEventService.formatJsonValue(value)}`\n}\n\nfunction additionalInfoTooltip(event: AuditLog) {\n  return Object.entries(event.params ?? {})\n    .map(([key, value]) => formatParam(key, value))\n    .join('\\n')\n}\n\n// A billing-route flip can overlap two loads against different backends; only\n// the latest may mutate state, so a superseded response is discarded.\nlet latestLoadToken = 0\n\nconst readWorkspaceEvents = (params: { page: number; limit: number }) => {\n  const rail = useBillingReadRail()\n  return rail === null\n    ? workspaceApi.getBillingEvents(params)\n    : readOnRail(() => rail.readEvents(params), 'getBillingEvents')\n}\n\nconst loadEvents = async () => {\n  const loadToken = ++latestLoadToken\n  loading.value = true\n  error.value = null\n\n  try {\n    const params = {\n      page: pagination.value.page,\n      limit: pagination.value.limit\n    }\n    const response = shouldUseWorkspaceBilling.value\n      ? await readWorkspaceEvents(params)\n      : await customerEventService.getMyEvents(params)\n\n    // Completion telemetry must run even when a mid-checkout route flip\n    // supersedes this load, since legacy and workspace backends emit different\n    // top-up events and the winning fetch may not carry the completion yet.\n    const completedTopup = usePendingTopup().consumeCompletedTopup(\n      response?.events\n    )\n    if (completedTopup) {\n      const telemetry = useTelemetry()\n      telemetry?.trackApiCreditTopupSucceeded()\n      telemetry?.trackBillingEvent({\n        operation: 'topup',\n        stage: 'succeeded',\n        outcome: 'success',\n        duration_ms: Date.now() - completedTopup.startedAtMs\n      })\n    }\n\n    if (loadToken !== latestLoadToken) return\n\n    // Undefined is a SUPERSEDED rail read: the scope moved on mid-request, so\n    // what is on screen belongs to the workspace we just left. Only the billing\n    // mode is watched, and a switch between two workspaces on the same mode\n    // does not remount this table — leaving the rows up would show one\n    // workspace's billing events under another.\n    if (response === undefined) {\n      dropRenderedEvents()\n      return\n    }\n\n    if (response) {\n      if (response.events) {\n        events.value = response.events\n      }\n\n      if (response.page) {\n        pagination.value.page = response.page\n      }\n\n      if (response.limit) {\n        pagination.value.limit = response.limit\n      }\n\n      if (response.total != null) {\n        pagination.value.total = response.total\n      }\n    } else {\n      const legacyError = shouldUseWorkspaceBilling.value\n        ? null\n        : customerEventService.error.value\n      error.value = legacyError || t('credits.loadEventsError')\n    }\n  } catch (err) {\n    if (loadToken !== latestLoadToken) return\n    error.value = t('credits.loadEventsUnknownError')\n    console.error('Error loading events:', err)\n  } finally {\n    if (loadToken === latestLoadToken) loading.value = false\n  }\n}\n\nconst onPageChange = (page: number) => {\n  pagination.value.page = page\n  loadEvents().catch((error) => {\n    console.error('Error loading events:', error)\n  })\n}\n\n/**\n * Forget what is on screen. A superseded read and a workspace switch both mean\n * the rendered rows belong to a scope this table has left, so they go before\n * the next read rather than after it settles.\n */\nconst dropRenderedEvents = () => {\n  events.value = []\n  pagination.value = { ...pagination.value, page: 1, total: 0 }\n}\n\nconst refresh = async () => {\n  pagination.value.page = 1\n  await loadEvents()\n}\n\nconst workspaceStore = useTeamWorkspaceStore()\n\n// The active workspace is watched alongside the billing mode: a switch between\n// two workspaces on the same mode leaves this table mounted, and without this\n// nothing reloads it at all when no read happens to be in flight.\nwatch(\n  [shouldUseWorkspaceBilling, () => workspaceStore.activeWorkspaceId],\n  ([, workspaceId], previous) => {\n    if (previous !== undefined && previous[1] !== workspaceId) {\n      dropRenderedEvents()\n    }\n    refresh().catch((error) => {\n      console.error('Error loading events:', error)\n    })\n  },\n  { immediate: true }\n)\n\ndefineExpose({\n  refresh\n})\n</script>\n","<template>\n  <div>\n    <div v-if=\"loading\" class=\"flex items-center justify-center p-8\">\n      <Spinner />\n    </div>\n    <div v-else-if=\"error\" class=\"p-4\">\n      <Message severity=\"error\">{{ error }}</Message>\n    </div>\n    <template v-else>\n      <Table>\n        <TableHeader>\n          <TableRow>\n            <TableHead>{{ $t('credits.eventType') }}</TableHead>\n            <TableHead>{{ $t('credits.details') }}</TableHead>\n            <TableHead>{{ $t('credits.time') }}</TableHead>\n            <TableHead>{{ $t('credits.additionalInfo') }}</TableHead>\n          </TableRow>\n        </TableHeader>\n        <TableBody>\n          <TableRow\n            v-for=\"(event, index) in events\"\n            :key=\"event.event_id ?? index\"\n          >\n            <TableCell>\n              <Badge\n                variant=\"badge\"\n                :severity=\"\n                  customerEventService.getEventSeverity(event.event_type ?? '')\n                \"\n              >\n                {{\n                  customerEventService.formatEventType(event.event_type ?? '')\n                }}\n              </Badge>\n            </TableCell>\n            <TableCell>\n              <div\n                v-if=\"event.event_type === EventType.CREDIT_ADDED\"\n                class=\"font-semibold text-success-background\"\n              >\n                {{ $t('credits.added') }} ${{\n                  customerEventService.formatAmount(eventAmount(event))\n                }}\n              </div>\n              <div v-else-if=\"event.event_type === EventType.ACCOUNT_CREATED\">\n                {{ $t('credits.accountInitialized') }}\n              </div>\n              <div\n                v-else-if=\"event.event_type === EventType.API_USAGE_COMPLETED\"\n                class=\"flex flex-col gap-1\"\n              >\n                <div class=\"font-semibold\">\n                  {{ event.params?.api_name || $t('credits.api') }}\n                </div>\n                <div class=\"text-sm text-muted-foreground\">\n                  {{ $t('credits.model') }}: {{ event.params?.model || '-' }}\n                </div>\n              </div>\n            </TableCell>\n            <TableCell>\n              {{ customerEventService.formatDate(event.createdAt ?? '') }}\n            </TableCell>\n            <TableCell>\n              <Button\n                v-if=\"customerEventService.hasAdditionalInfo(event)\"\n                :tooltip=\"additionalInfoTooltip(event)\"\n                variant=\"textonly\"\n                size=\"icon-sm\"\n                :aria-label=\"$t('credits.additionalInfo')\"\n              >\n                <i class=\"pi pi-info-circle\" />\n              </Button>\n            </TableCell>\n          </TableRow>\n        </TableBody>\n      </Table>\n      <Pagination\n        v-if=\"pagination.total > pagination.limit\"\n        :page=\"pagination.page\"\n        :total=\"pagination.total\"\n        :items-per-page=\"pagination.limit\"\n        class=\"mt-3\"\n        @update:page=\"onPageChange\"\n      />\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport Message from '@/components/ui/message/Message.vue'\nimport Pagination from '@/components/ui/pagination/Pagination.vue'\nimport Spinner from '@/components/ui/spinner/Spinner.vue'\nimport Table from '@/components/ui/table/Table.vue'\nimport TableBody from '@/components/ui/table/TableBody.vue'\nimport TableCell from '@/components/ui/table/TableCell.vue'\nimport TableHead from '@/components/ui/table/TableHead.vue'\nimport TableHeader from '@/components/ui/table/TableHeader.vue'\nimport TableRow from '@/components/ui/table/TableRow.vue'\nimport { formatCreditsFromUsd } from '@/base/credits/comfyCredits'\nimport { useBillingRouting } from '@/composables/billing/useBillingRouting'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { workspaceApi } from '@/platform/workspace/api/workspaceApi'\nimport { readOnRail } from '@/platform/workspace/composables/readOnRail'\nimport { useBillingReadRail } from '@/platform/workspace/composables/useBillingReadRail'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { usePendingTopup } from '@/composables/billing/usePendingTopup'\nimport type { AuditLog } from '@/services/customerEventsService'\nimport {\n  EventType,\n  useCustomerEventsService\n} from '@/services/customerEventsService'\n\nconst { t, locale } = useI18n()\n\nconst events = ref<AuditLog[]>([])\nconst loading = ref(true)\nconst error = ref<string | null>(null)\n\nconst customerEventService = useCustomerEventsService()\n\nconst { shouldUseWorkspaceBilling } = useBillingRouting()\n\nconst pagination = ref({\n  page: 1,\n  limit: 7,\n  total: 0\n})\n\nfunction toFiniteNumber(raw: unknown) {\n  const value = typeof raw === 'string' && raw.trim() ? Number(raw) : raw\n  return typeof value === 'number' && Number.isFinite(value) ? value : undefined\n}\n\nfunction eventAmount(event: AuditLog) {\n  return toFiniteNumber(event.params?.amount)\n}\n\nfunction formatChargeCredits(microUsd: number) {\n  const amount = formatCreditsFromUsd({\n    usd: microUsd / 1_000_000,\n    locale: locale.value,\n    numberOptions: { minimumFractionDigits: 0, maximumFractionDigits: 0 }\n  })\n  return `${amount} ${t('credits.credits')}`\n}\n\nfunction formatParam(key: string, value: unknown) {\n  const microUsd =\n    key === 'charge_micro_usd' ? toFiniteNumber(value) : undefined\n  if (microUsd !== undefined) {\n    return `${t('credits.charge')}: ${formatChargeCredits(microUsd)}`\n  }\n  return `${customerEventService.formatJsonKey(key)}: ${customerEventService.formatJsonValue(value)}`\n}\n\nfunction additionalInfoTooltip(event: AuditLog) {\n  return Object.entries(event.params ?? {})\n    .map(([key, value]) => formatParam(key, value))\n    .join('\\n')\n}\n\n// A billing-route flip can overlap two loads against different backends; only\n// the latest may mutate state, so a superseded response is discarded.\nlet latestLoadToken = 0\n\nconst readWorkspaceEvents = (params: { page: number; limit: number }) => {\n  const rail = useBillingReadRail()\n  return rail === null\n    ? workspaceApi.getBillingEvents(params)\n    : readOnRail(() => rail.readEvents(params), 'getBillingEvents')\n}\n\nconst loadEvents = async () => {\n  const loadToken = ++latestLoadToken\n  loading.value = true\n  error.value = null\n\n  try {\n    const params = {\n      page: pagination.value.page,\n      limit: pagination.value.limit\n    }\n    const response = shouldUseWorkspaceBilling.value\n      ? await readWorkspaceEvents(params)\n      : await customerEventService.getMyEvents(params)\n\n    // Completion telemetry must run even when a mid-checkout route flip\n    // supersedes this load, since legacy and workspace backends emit different\n    // top-up events and the winning fetch may not carry the completion yet.\n    const completedTopup = usePendingTopup().consumeCompletedTopup(\n      response?.events\n    )\n    if (completedTopup) {\n      const telemetry = useTelemetry()\n      telemetry?.trackApiCreditTopupSucceeded()\n      telemetry?.trackBillingEvent({\n        operation: 'topup',\n        stage: 'succeeded',\n        outcome: 'success',\n        duration_ms: Date.now() - completedTopup.startedAtMs\n      })\n    }\n\n    if (loadToken !== latestLoadToken) return\n\n    // Undefined is a SUPERSEDED rail read: the scope moved on mid-request, so\n    // what is on screen belongs to the workspace we just left. Only the billing\n    // mode is watched, and a switch between two workspaces on the same mode\n    // does not remount this table — leaving the rows up would show one\n    // workspace's billing events under another.\n    if (response === undefined) {\n      dropRenderedEvents()\n      return\n    }\n\n    if (response) {\n      if (response.events) {\n        events.value = response.events\n      }\n\n      if (response.page) {\n        pagination.value.page = response.page\n      }\n\n      if (response.limit) {\n        pagination.value.limit = response.limit\n      }\n\n      if (response.total != null) {\n        pagination.value.total = response.total\n      }\n    } else {\n      const legacyError = shouldUseWorkspaceBilling.value\n        ? null\n        : customerEventService.error.value\n      error.value = legacyError || t('credits.loadEventsError')\n    }\n  } catch (err) {\n    if (loadToken !== latestLoadToken) return\n    error.value = t('credits.loadEventsUnknownError')\n    console.error('Error loading events:', err)\n  } finally {\n    if (loadToken === latestLoadToken) loading.value = false\n  }\n}\n\nconst onPageChange = (page: number) => {\n  pagination.value.page = page\n  loadEvents().catch((error) => {\n    console.error('Error loading events:', error)\n  })\n}\n\n/**\n * Forget what is on screen. A superseded read and a workspace switch both mean\n * the rendered rows belong to a scope this table has left, so they go before\n * the next read rather than after it settles.\n */\nconst dropRenderedEvents = () => {\n  events.value = []\n  pagination.value = { ...pagination.value, page: 1, total: 0 }\n}\n\nconst refresh = async () => {\n  pagination.value.page = 1\n  await loadEvents()\n}\n\nconst workspaceStore = useTeamWorkspaceStore()\n\n// The active workspace is watched alongside the billing mode: a switch between\n// two workspaces on the same mode leaves this table mounted, and without this\n// nothing reloads it at all when no read happens to be in flight.\nwatch(\n  [shouldUseWorkspaceBilling, () => workspaceStore.activeWorkspaceId],\n  ([, workspaceId], previous) => {\n    if (previous !== undefined && previous[1] !== workspaceId) {\n      dropRenderedEvents()\n    }\n    refresh().catch((error) => {\n      console.error('Error loading events:', error)\n    })\n  },\n  { immediate: true }\n)\n\ndefineExpose({\n  refresh\n})\n</script>\n","import { computed, toValue } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport {\n  centsToCredits,\n  formatCreditsFromCents\n} from '@/base/credits/comfyCredits'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\n\n/**\n * Composable for handling subscription credit calculations and formatting.\n *\n * Uses useBillingContext which automatically selects the correct billing source:\n * - If team workspaces feature is disabled: uses legacy (/customers)\n * - If team workspaces feature is enabled:\n *   - Personal workspace: uses legacy (/customers)\n *   - Team workspace: uses workspace (/billing)\n */\n/**\n * Formats a cent value to display credits.\n * Backend returns cents despite the *_micros naming convention.\n */\nfunction formatBalance(maybeCents: number | undefined, locale: string): string {\n  const cents = maybeCents ?? 0\n  return formatCreditsFromCents({\n    cents,\n    locale,\n    numberOptions: {\n      minimumFractionDigits: 0,\n      maximumFractionDigits: 0\n    }\n  })\n}\n\nexport function useSubscriptionCredits() {\n  const billingContext = useBillingContext()\n  const { locale } = useI18n()\n\n  const totalCredits = computed(() => {\n    const balance = toValue(billingContext.balance)\n    return formatBalance(balance?.amountMicros, locale.value)\n  })\n\n  const monthlyBonusCredits = computed(() => {\n    const balance = toValue(billingContext.balance)\n    return formatBalance(balance?.cloudCreditBalanceMicros, locale.value)\n  })\n\n  const prepaidCredits = computed(() => {\n    const balance = toValue(billingContext.balance)\n    return formatBalance(balance?.prepaidBalanceMicros, locale.value)\n  })\n\n  const isLoadingBalance = computed(() => toValue(billingContext.isLoading))\n\n  const creditsFromMicros = (maybeCents: number | undefined): number =>\n    centsToCredits(maybeCents ?? 0)\n\n  const monthlyBonusCreditsValue = computed(() =>\n    creditsFromMicros(toValue(billingContext.balance)?.cloudCreditBalanceMicros)\n  )\n\n  const prepaidCreditsValue = computed(() =>\n    creditsFromMicros(toValue(billingContext.balance)?.prepaidBalanceMicros)\n  )\n\n  return {\n    totalCredits,\n    monthlyBonusCredits,\n    prepaidCredits,\n    monthlyBonusCreditsValue,\n    prepaidCreditsValue,\n    isLoadingBalance\n  }\n}\n","import { clamp } from 'es-toolkit'\n\ninterface MonthlyCreditsUsage {\n  /** Credits consumed from the monthly allowance (never negative). */\n  used: number\n  /** Credits left of the monthly allowance, clamped to `0..monthlyTotal`. */\n  remaining: number\n  /** Fraction (0–1) of the monthly allowance consumed — drives the bar fill. */\n  usedFraction: number\n}\n\n/**\n * Computes monthly credit usage for the credits bar. `remaining` clamps to the\n * allowance, and `used` is its complement, so `used + remaining` always equals\n * `monthlyTotal` — a balance above the allowance cannot read as more left than\n * the plan grants.\n */\nexport function computeMonthlyUsage(\n  monthlyRemaining: number,\n  monthlyTotal: number\n): MonthlyCreditsUsage {\n  if (monthlyTotal <= 0) {\n    return { used: 0, remaining: 0, usedFraction: 0 }\n  }\n\n  const remaining = clamp(monthlyRemaining, 0, monthlyTotal)\n  const used = monthlyTotal - remaining\n\n  return { used, remaining, usedFraction: used / monthlyTotal }\n}\n","<template>\n  <div\n    :class=\"\n      cn(\n        '@container relative flex flex-col gap-6 rounded-2xl border border-interface-stroke bg-modal-panel-background px-6 py-5',\n        inactivePlan && 'text-muted'\n      )\n    \"\n  >\n    <Button\n      variant=\"muted-textonly\"\n      size=\"icon-sm\"\n      class=\"absolute top-4 right-4\"\n      :loading=\"isLoadingBalance\"\n      :aria-label=\"$t('subscription.refreshCredits')\"\n      @click=\"handleRefresh\"\n    >\n      <i class=\"icon-[lucide--refresh-cw] size-4 text-text-secondary\" />\n    </Button>\n\n    <div class=\"flex flex-col gap-1\">\n      <div class=\"text-sm text-muted\">\n        {{ $t('subscription.totalCredits') }}\n      </div>\n      <Skeleton v-if=\"isLoadingBalance\" class=\"h-8 w-32\" />\n      <div v-else class=\"flex items-baseline gap-2\">\n        <i\n          :class=\"\n            cn(\n              'icon-[lucide--coins] size-4 self-center',\n              !inactivePlan && 'text-credit'\n            )\n          \"\n        />\n        <span class=\"text-2xl leading-none font-bold\">{{ displayTotal }}</span>\n        <span class=\"text-sm text-muted @max-[300px]:hidden\">{{\n          $t('subscription.remaining')\n        }}</span>\n      </div>\n    </div>\n\n    <template v-if=\"showBreakdown\">\n      <div\n        v-if=\"emptyStateNotice\"\n        class=\"flex items-start gap-2 rounded-lg bg-base-background p-3 text-sm\"\n      >\n        <i\n          class=\"mt-0.5 icon-[lucide--info] size-4 shrink-0 text-base-foreground\"\n        />\n        <div class=\"flex flex-col gap-1\">\n          <span class=\"text-base-foreground\">{{ emptyStateNotice.title }}</span>\n          <span class=\"text-muted\">{{ emptyStateNotice.description }}</span>\n        </div>\n      </div>\n\n      <div\n        v-if=\"showBar\"\n        :class=\"cn('flex flex-col gap-2', isMonthlyDepleted && 'opacity-30')\"\n      >\n        <div class=\"flex items-center justify-between text-sm\">\n          <span class=\"text-text-primary\">{{ allowanceLabel }}</span>\n          <span class=\"text-muted\">\n            {{ refillsLabel }}\n          </span>\n        </div>\n        <div\n          role=\"progressbar\"\n          :aria-valuenow=\"usage.used\"\n          :aria-valuemin=\"0\"\n          :aria-valuemax=\"creditPoolTotalCredits ?? 0\"\n          :aria-valuetext=\"monthlyUsageLabel\"\n          class=\"h-2 w-full overflow-hidden rounded-full bg-secondary-background-hover\"\n        >\n          <div\n            class=\"h-full rounded-full bg-credit\"\n            :style=\"{ width: usedBarWidth }\"\n          />\n        </div>\n        <div class=\"flex items-center justify-between gap-2 text-sm\">\n          <Skeleton\n            v-if=\"isLoadingBalance\"\n            class=\"h-4 w-20 @max-[300px]:hidden\"\n          />\n          <span v-else class=\"text-muted @max-[300px]:hidden\">\n            {{ $t('subscription.creditsUsed', { used: usedDisplay }) }}\n          </span>\n          <Skeleton v-if=\"isLoadingBalance\" class=\"h-4 w-36\" />\n          <span\n            v-else\n            class=\"flex items-center gap-1 font-bold text-text-primary\"\n          >\n            <i class=\"icon-[lucide--coins] size-4 text-credit\" />\n            <span class=\"@max-[180px]:hidden\">\n              {{\n                $t('subscription.creditsLeftOfTotal', {\n                  remaining: monthlyRemainingDisplay,\n                  total: creditPoolTotalDisplay\n                })\n              }}\n            </span>\n            <span class=\"hidden @max-[180px]:inline\">\n              {{\n                $t('subscription.creditsLeftOfTotal', {\n                  remaining: monthlyRemainingCompact,\n                  total: creditPoolTotalCompact\n                })\n              }}\n            </span>\n          </span>\n        </div>\n      </div>\n\n      <div class=\"h-px w-full bg-interface-stroke\" />\n\n      <div class=\"flex flex-col gap-2\">\n        <div\n          class=\"flex items-center justify-between gap-2 text-sm @max-[300px]:flex-col @max-[300px]:items-start\"\n        >\n          <span class=\"flex items-center gap-1 text-text-primary\">\n            {{ $t('subscription.additionalCredits') }}\n            <Button\n              :tooltip=\"$t('subscription.additionalCreditsTooltip')\"\n              variant=\"muted-textonly\"\n              size=\"icon-sm\"\n              :aria-label=\"$t('subscription.additionalCreditsInfo')\"\n              class=\"text-muted\"\n            >\n              <i class=\"icon-[lucide--info] size-4\" />\n            </Button>\n            <span\n              v-if=\"isSpendingAdditional\"\n              class=\"flex h-3.5 items-center rounded-full bg-base-foreground px-1 text-2xs/none font-semibold text-base-background uppercase\"\n            >\n              {{ $t('subscription.additionalCreditsInUse') }}\n            </span>\n          </span>\n          <Skeleton v-if=\"isLoadingBalance\" class=\"h-4 w-12\" />\n          <span\n            v-else\n            class=\"flex items-center gap-1 font-bold text-text-primary\"\n          >\n            <i class=\"icon-[lucide--coins] size-4 text-credit\" />\n            {{ displayPrepaid }}\n          </span>\n        </div>\n        <span\n          v-if=\"!isDurationUnknown\"\n          class=\"text-sm text-muted @max-[300px]:hidden\"\n        >\n          {{ usedAfterAllowanceLabel }}\n        </span>\n      </div>\n    </template>\n\n    <template v-else-if=\"showsInactivePlanState\">\n      <div class=\"h-px w-full bg-interface-stroke\" />\n      <div class=\"flex flex-col gap-2\">\n        <div class=\"flex items-center justify-between gap-2 text-sm\">\n          <span class=\"flex items-center gap-1\">\n            {{ $t('subscription.additionalCredits') }}\n            <Button\n              :tooltip=\"$t('subscription.additionalCreditsTooltip')\"\n              variant=\"muted-textonly\"\n              size=\"icon-sm\"\n              :aria-label=\"$t('subscription.additionalCreditsInfo')\"\n              class=\"text-muted\"\n            >\n              <i class=\"icon-[lucide--info] size-4\" />\n            </Button>\n          </span>\n          <span class=\"flex items-center gap-1 font-bold\">\n            <i class=\"icon-[lucide--coins] size-4\" />\n            {{ displayPrepaid }}\n          </span>\n        </div>\n        <span class=\"text-sm\">\n          {{ inactiveCreditsNote }}\n        </span>\n      </div>\n    </template>\n\n    <div v-if=\"showActionButton\" class=\"flex flex-col gap-3\">\n      <Button\n        v-if=\"canTopUp\"\n        :variant=\"isOutOfCredits ? 'inverted' : 'secondary'\"\n        size=\"lg\"\n        :class=\"\n          cn(\n            'w-full font-normal',\n            !isOutOfCredits &&\n              'bg-interface-menu-component-surface-selected text-text-primary'\n          )\n        \"\n        @click=\"handleAddCredits\"\n      >\n        {{ $t('subscription.addCredits') }}\n      </Button>\n      <Button\n        v-else\n        variant=\"subscribe\"\n        size=\"lg\"\n        class=\"w-full font-normal\"\n        @click=\"handleUpgradeToAddCredits\"\n      >\n        {{ $t('subscription.upgradeToAddCredits') }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useEventListener } from '@vueuse/core'\nimport { computed, onMounted } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\n\nimport { formatCredits } from '@/base/credits/comfyCredits'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { useSubscriptionCredits } from '@/platform/cloud/subscription/composables/useSubscriptionCredits'\nimport { useSubscriptionDialog } from '@/platform/cloud/subscription/composables/useSubscriptionDialog'\nimport {\n  DEFAULT_TIER_KEY,\n  isSalesManagedTier,\n  toTierKey,\n  getTierCredits\n} from '@/platform/cloud/subscription/constants/tierPricing'\nimport { computeMonthlyUsage } from '@/platform/cloud/subscription/utils/creditsProgress'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { paymentIntentSourceForAddCreditsClick } from '@/platform/telemetry/utils/paymentIntentSource'\nimport { usePendingTopup } from '@/composables/billing/usePendingTopup'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { useCustomerEventsService } from '@/services/customerEventsService'\nimport { useBillingDialogs } from '@/composables/billing/useBillingDialogs'\n\nconst { zeroState = false, inactivePlan } = defineProps<{\n  /** Forces the zero-credit display (e.g. unsubscribed / member view). */\n  zeroState?: boolean\n  inactivePlan?: boolean\n}>()\n\nconst { locale, t } = useI18n()\n\nconst {\n  subscription,\n  balance,\n  canAccessSubscriptionFeatures,\n  currentTeamCreditStop,\n  fetchBalance,\n  fetchStatus\n} = useBillingContext()\nconst { canTopUp, canSubscribeSelfServe } = useBillingCapabilities()\nconst {\n  prepaidCredits,\n  totalCredits,\n  monthlyBonusCreditsValue,\n  prepaidCreditsValue,\n  isLoadingBalance\n} = useSubscriptionCredits()\nconst { wrapWithErrorHandlingAsync } = useErrorHandling()\nconst { showPricingTable } = useSubscriptionDialog()\nconst customerEventsService = useCustomerEventsService()\nconst { showTopUpCreditsDialog } = useBillingDialogs()\nconst telemetry = useTelemetry()\nconst { pendingTopupNeedsRefresh, consumeCompletedTopup } = usePendingTopup()\n\nconst tierKey = computed(() => {\n  const tier = subscription.value?.tier\n  if (!tier) return DEFAULT_TIER_KEY\n  return toTierKey(tier) ?? DEFAULT_TIER_KEY\n})\n\nconst isAnnualBilling = computed(\n  () => subscription.value?.duration === 'ANNUAL'\n)\n\n// Paid plan with no reported duration: the allowance cycle is unknown, so no\n// total is shown rather than guessing monthly. Free has no duration by design,\n// and Founders Edition is a fixed monthly grant.\nconst isDurationUnknown = computed(\n  () =>\n    !!subscription.value?.tier &&\n    !subscription.value.duration &&\n    tierKey.value !== 'free' &&\n    tierKey.value !== 'founder'\n)\n\nconst creditPoolTotalCredits = computed<number | null>(() => {\n  if (isDurationUnknown.value) return null\n  const monthlyCredits =\n    currentTeamCreditStop.value?.credits_monthly ??\n    (isSalesManagedTier(subscription.value?.tier)\n      ? null\n      : getTierCredits(tierKey.value))\n  if (monthlyCredits === null) return null\n  return isAnnualBilling.value ? monthlyCredits * 12 : monthlyCredits\n})\n\n// Tier decides the note, not the state: a lapsed sales-managed plan gets the\n// same disabled shape as self-serve (cloud#8001 closed its can_top_up, so the\n// old exclusion left a bare balance with no explanation) — only the route\n// back differs, the account manager rather than a Reactivate button. The\n// state keys on the prop rather than can_top_up because that capability is\n// rollout-defaulted and fails open for owners on an unreadable snapshot.\nconst showsInactivePlanState = computed(() => inactivePlan === true)\n\nconst inactiveCreditsNote = computed(() => {\n  if (!isSalesManagedTier(subscription.value?.tier))\n    return t('subscription.reactivateToUseCredits')\n  return prepaidCreditsValue.value > 0\n    ? t('subscription.salesManagedInactiveCreditsNote')\n    : t('subscription.salesManagedCreditsEndedNote')\n})\n\nconst usage = computed(() =>\n  computeMonthlyUsage(\n    monthlyBonusCreditsValue.value,\n    creditPoolTotalCredits.value ?? 0\n  )\n)\n\nconst refillsDateShort = computed(() => {\n  const raw = subscription.value?.renewalDate\n  if (!raw) return ''\n  const date = new Date(raw)\n  return Number.isNaN(date.getTime())\n    ? ''\n    : date.toLocaleDateString(locale.value, { month: 'short', day: 'numeric' })\n})\n\nconst hasRefillsDate = computed(() => refillsDateShort.value !== '')\n\nconst refillsLabel = computed(() =>\n  hasRefillsDate.value\n    ? t('subscription.refillsDate', { date: refillsDateShort.value })\n    : t('subscription.refillsNextCycle')\n)\n\nconst allowanceLabel = computed(() =>\n  t(isAnnualBilling.value ? 'subscription.yearly' : 'subscription.monthly')\n)\n\nconst usedAfterAllowanceLabel = computed(() =>\n  t(\n    isAnnualBilling.value\n      ? 'subscription.usedAfterYearly'\n      : 'subscription.usedAfterMonthly'\n  )\n)\n\nconst formatCreditCount = (value: number) =>\n  formatCredits({\n    value,\n    locale: locale.value,\n    numberOptions: { maximumFractionDigits: 0 }\n  })\n\nconst creditPoolTotalDisplay = computed(() => {\n  const total = creditPoolTotalCredits.value\n  return total === null ? '—' : formatCreditCount(total)\n})\n\nconst usedDisplay = computed(() => formatCreditCount(usage.value.used))\nconst monthlyRemainingDisplay = computed(() =>\n  formatCreditCount(usage.value.remaining)\n)\n\nconst compactNumber = computed(\n  () => new Intl.NumberFormat(locale.value, { notation: 'compact' })\n)\nconst monthlyRemainingCompact = computed(() =>\n  compactNumber.value.format(usage.value.remaining)\n)\nconst creditPoolTotalCompact = computed(() => {\n  const total = creditPoolTotalCredits.value\n  return total === null ? '—' : compactNumber.value.format(total)\n})\n\nconst displayTotal = computed(() =>\n  zeroState || showsInactivePlanState.value\n    ? formatCreditCount(0)\n    : totalCredits.value\n)\n// An ended sales-managed plan retains its prepaid balance: the note beside\n// this number says the credits become spendable once the plan is restored,\n// so the amount must survive the inactive state rather than read 0.\nconst retainsPrepaidWhileInactive = computed(() =>\n  isSalesManagedTier(subscription.value?.tier)\n)\nconst displayPrepaid = computed(() => {\n  if (zeroState) return formatCreditCount(0)\n  if (showsInactivePlanState.value && !retainsPrepaidWhileInactive.value) {\n    return formatCreditCount(0)\n  }\n  return prepaidCredits.value\n})\nconst usedBarWidth = computed(\n  () => `${(usage.value.usedFraction * 100).toFixed(2)}%`\n)\nconst monthlyUsageLabel = computed(() =>\n  t(\n    isAnnualBilling.value\n      ? 'subscription.yearlyUsageProgress'\n      : 'subscription.monthlyUsageProgress',\n    {\n      used: usedDisplay.value,\n      total: creditPoolTotalDisplay.value\n    }\n  )\n)\n\nconst showBreakdown = computed(\n  () =>\n    canAccessSubscriptionFeatures.value &&\n    !zeroState &&\n    !showsInactivePlanState.value\n)\n// The monthly allowance bar is a Cloud-only presentation; Local/Desktop shows\n// only the total and additional-credit balances.\nconst showBar = computed(\n  () =>\n    isCloud &&\n    showBreakdown.value &&\n    creditPoolTotalCredits.value !== null &&\n    creditPoolTotalCredits.value > 0\n)\nconst showActionButton = computed(\n  () =>\n    (canTopUp.value || canSubscribeSelfServe.value) &&\n    !zeroState &&\n    !showsInactivePlanState.value\n)\n\nconst isMonthlyDepleted = computed(\n  () =>\n    showBar.value &&\n    !isLoadingBalance.value &&\n    balance.value != null &&\n    monthlyBonusCreditsValue.value <= 0\n)\n// Depletion needs only the remaining allowance, not its cycle, so the\n// cycle-neutral signals still work when the duration is unknown.\nconst isAllowanceDepleted = computed(\n  () =>\n    isMonthlyDepleted.value ||\n    (isDurationUnknown.value &&\n      isCloud &&\n      showBreakdown.value &&\n      !isLoadingBalance.value &&\n      balance.value != null &&\n      monthlyBonusCreditsValue.value <= 0)\n)\nconst isOutOfCredits = computed(\n  () => isAllowanceDepleted.value && prepaidCreditsValue.value <= 0\n)\nconst isSpendingAdditional = computed(\n  () => isAllowanceDepleted.value && prepaidCreditsValue.value > 0\n)\n\nconst emptyStateNotice = computed(() => {\n  if (isOutOfCredits.value) {\n    return {\n      title: hasRefillsDate.value\n        ? t('subscription.outOfCreditsTitle', { date: refillsDateShort.value })\n        : t('subscription.outOfCreditsTitleNoDate'),\n      description: t('subscription.outOfCreditsDescription')\n    }\n  }\n  if (isMonthlyDepleted.value) {\n    return {\n      title: hasRefillsDate.value\n        ? t(\n            isAnnualBilling.value\n              ? 'subscription.yearlyCreditsUsedUpTitle'\n              : 'subscription.monthlyCreditsUsedUpTitle',\n            {\n              date: refillsDateShort.value\n            }\n          )\n        : t(\n            isAnnualBilling.value\n              ? 'subscription.yearlyCreditsUsedUpTitleNoDate'\n              : 'subscription.monthlyCreditsUsedUpTitleNoDate'\n          ),\n      description: t('subscription.monthlyCreditsUsedUpDescription')\n    }\n  }\n  return null\n})\n\nasync function refreshCredits() {\n  const results = await Promise.allSettled([fetchBalance(), fetchStatus()])\n  for (const result of results) {\n    if (result.status === 'rejected') throw result.reason\n  }\n\n  if (!pendingTopupNeedsRefresh()) return\n\n  const response = await customerEventsService.getMyEvents({\n    page: 1,\n    limit: 10\n  })\n  if (!response) {\n    throw new Error(\n      customerEventsService.error.value ?? 'Fetching customer events failed'\n    )\n  }\n  const completedTopup = consumeCompletedTopup(response.events)\n  if (completedTopup) {\n    telemetry?.trackApiCreditTopupSucceeded()\n    telemetry?.trackBillingEvent({\n      operation: 'topup',\n      stage: 'succeeded',\n      outcome: 'success',\n      duration_ms: Date.now() - completedTopup.startedAtMs\n    })\n  }\n}\n\nlet refreshRequested = false\nlet activeRefresh: Promise<void> | null = null\n\nasync function refreshLatestCredits() {\n  refreshRequested = true\n  if (activeRefresh) return activeRefresh\n\n  activeRefresh = (async () => {\n    let lastError: unknown\n    while (refreshRequested) {\n      refreshRequested = false\n      try {\n        await refreshCredits()\n        lastError = undefined\n      } catch (error) {\n        lastError = error\n      }\n    }\n    if (lastError) throw lastError\n  })()\n\n  try {\n    await activeRefresh\n  } finally {\n    activeRefresh = null\n  }\n}\n\nconst handleRefresh = wrapWithErrorHandlingAsync(refreshLatestCredits)\n\nfunction handleAddCredits() {\n  telemetry?.trackAddApiCreditButtonClicked({ source: 'credits_panel' })\n  void showTopUpCreditsDialog({\n    source: paymentIntentSourceForAddCreditsClick('credits_panel')\n  })\n}\n\nfunction handleUpgradeToAddCredits() {\n  showPricingTable({ reason: 'upgrade_to_add_credits' })\n}\n\nasync function handleWindowFocus() {\n  if (pendingTopupNeedsRefresh()) {\n    await handleRefresh()\n  }\n}\n\nuseEventListener(window, 'focus', () => void handleWindowFocus())\n\nonMounted(handleRefresh)\n</script>\n","<template>\n  <div\n    :class=\"\n      cn(\n        '@container relative flex flex-col gap-6 rounded-2xl border border-interface-stroke bg-modal-panel-background px-6 py-5',\n        inactivePlan && 'text-muted'\n      )\n    \"\n  >\n    <Button\n      variant=\"muted-textonly\"\n      size=\"icon-sm\"\n      class=\"absolute top-4 right-4\"\n      :loading=\"isLoadingBalance\"\n      :aria-label=\"$t('subscription.refreshCredits')\"\n      @click=\"handleRefresh\"\n    >\n      <i class=\"icon-[lucide--refresh-cw] size-4 text-text-secondary\" />\n    </Button>\n\n    <div class=\"flex flex-col gap-1\">\n      <div class=\"text-sm text-muted\">\n        {{ $t('subscription.totalCredits') }}\n      </div>\n      <Skeleton v-if=\"isLoadingBalance\" class=\"h-8 w-32\" />\n      <div v-else class=\"flex items-baseline gap-2\">\n        <i\n          :class=\"\n            cn(\n              'icon-[lucide--coins] size-4 self-center',\n              !inactivePlan && 'text-credit'\n            )\n          \"\n        />\n        <span class=\"text-2xl leading-none font-bold\">{{ displayTotal }}</span>\n        <span class=\"text-sm text-muted @max-[300px]:hidden\">{{\n          $t('subscription.remaining')\n        }}</span>\n      </div>\n    </div>\n\n    <template v-if=\"showBreakdown\">\n      <div\n        v-if=\"emptyStateNotice\"\n        class=\"flex items-start gap-2 rounded-lg bg-base-background p-3 text-sm\"\n      >\n        <i\n          class=\"mt-0.5 icon-[lucide--info] size-4 shrink-0 text-base-foreground\"\n        />\n        <div class=\"flex flex-col gap-1\">\n          <span class=\"text-base-foreground\">{{ emptyStateNotice.title }}</span>\n          <span class=\"text-muted\">{{ emptyStateNotice.description }}</span>\n        </div>\n      </div>\n\n      <div\n        v-if=\"showBar\"\n        :class=\"cn('flex flex-col gap-2', isMonthlyDepleted && 'opacity-30')\"\n      >\n        <div class=\"flex items-center justify-between text-sm\">\n          <span class=\"text-text-primary\">{{ allowanceLabel }}</span>\n          <span class=\"text-muted\">\n            {{ refillsLabel }}\n          </span>\n        </div>\n        <div\n          role=\"progressbar\"\n          :aria-valuenow=\"usage.used\"\n          :aria-valuemin=\"0\"\n          :aria-valuemax=\"creditPoolTotalCredits ?? 0\"\n          :aria-valuetext=\"monthlyUsageLabel\"\n          class=\"h-2 w-full overflow-hidden rounded-full bg-secondary-background-hover\"\n        >\n          <div\n            class=\"h-full rounded-full bg-credit\"\n            :style=\"{ width: usedBarWidth }\"\n          />\n        </div>\n        <div class=\"flex items-center justify-between gap-2 text-sm\">\n          <Skeleton\n            v-if=\"isLoadingBalance\"\n            class=\"h-4 w-20 @max-[300px]:hidden\"\n          />\n          <span v-else class=\"text-muted @max-[300px]:hidden\">\n            {{ $t('subscription.creditsUsed', { used: usedDisplay }) }}\n          </span>\n          <Skeleton v-if=\"isLoadingBalance\" class=\"h-4 w-36\" />\n          <span\n            v-else\n            class=\"flex items-center gap-1 font-bold text-text-primary\"\n          >\n            <i class=\"icon-[lucide--coins] size-4 text-credit\" />\n            <span class=\"@max-[180px]:hidden\">\n              {{\n                $t('subscription.creditsLeftOfTotal', {\n                  remaining: monthlyRemainingDisplay,\n                  total: creditPoolTotalDisplay\n                })\n              }}\n            </span>\n            <span class=\"hidden @max-[180px]:inline\">\n              {{\n                $t('subscription.creditsLeftOfTotal', {\n                  remaining: monthlyRemainingCompact,\n                  total: creditPoolTotalCompact\n                })\n              }}\n            </span>\n          </span>\n        </div>\n      </div>\n\n      <div class=\"h-px w-full bg-interface-stroke\" />\n\n      <div class=\"flex flex-col gap-2\">\n        <div\n          class=\"flex items-center justify-between gap-2 text-sm @max-[300px]:flex-col @max-[300px]:items-start\"\n        >\n          <span class=\"flex items-center gap-1 text-text-primary\">\n            {{ $t('subscription.additionalCredits') }}\n            <Button\n              :tooltip=\"$t('subscription.additionalCreditsTooltip')\"\n              variant=\"muted-textonly\"\n              size=\"icon-sm\"\n              :aria-label=\"$t('subscription.additionalCreditsInfo')\"\n              class=\"text-muted\"\n            >\n              <i class=\"icon-[lucide--info] size-4\" />\n            </Button>\n            <span\n              v-if=\"isSpendingAdditional\"\n              class=\"flex h-3.5 items-center rounded-full bg-base-foreground px-1 text-2xs/none font-semibold text-base-background uppercase\"\n            >\n              {{ $t('subscription.additionalCreditsInUse') }}\n            </span>\n          </span>\n          <Skeleton v-if=\"isLoadingBalance\" class=\"h-4 w-12\" />\n          <span\n            v-else\n            class=\"flex items-center gap-1 font-bold text-text-primary\"\n          >\n            <i class=\"icon-[lucide--coins] size-4 text-credit\" />\n            {{ displayPrepaid }}\n          </span>\n        </div>\n        <span\n          v-if=\"!isDurationUnknown\"\n          class=\"text-sm text-muted @max-[300px]:hidden\"\n        >\n          {{ usedAfterAllowanceLabel }}\n        </span>\n      </div>\n    </template>\n\n    <template v-else-if=\"showsInactivePlanState\">\n      <div class=\"h-